WITH RECURSIVE p AS (SELECT coalesce(%s::text,'') ma_sp_me,coalesce(%s::text,'') ma_sp_con,coalesce(%s::text,'') ma_btp_vt,coalesce(%s::text,'') ma_cong_doan,coalesce(%s::text,'') ma_dvcs,%s::integer uid,%s::integer lim), s AS (SELECT p.* FROM p JOIN public.userinfo u ON u.user_id=p.uid), bom AS (SELECT b.* FROM public.mfbom b CROSS JOIN s WHERE b.status='1' AND current_date BETWEEN b.valid_from AND b.valid_to AND (s.ma_dvcs='' OR b.branch_list=ANY(string_to_array(s.ma_dvcs,','))) AND b.bom_version IN (SELECT max(x.bom_version) FROM public.mfbom x WHERE x.product_code=b.product_code AND x.status='1' AND current_date BETWEEN x.valid_from AND x.valid_to GROUP BY x.product_code)), tree AS (SELECT b.product_code ma_sp_me,m.bom_code,m.product_code ma_sp_con,m.material_code ma_btp_vt,m.bom_version,m.uom,m.quantity,m.operation_code,m.valid_from,m.valid_to,m.sl_sp sl_sp_material,m.sl_gate_runner,1 cap_bom,ARRAY[m.bom_code||':'||m.material_code] path FROM bom b JOIN public.mfbom_material m ON m.bom_code=b.bom_code WHERE NOT EXISTS(SELECT 1 FROM public.mfbom_material x WHERE x.material_code=m.product_code) UNION ALL SELECT t.ma_sp_me,m.bom_code,m.product_code,m.material_code,m.bom_version,m.uom,m.quantity,m.operation_code,m.valid_from,m.valid_to,m.sl_sp,m.sl_gate_runner,t.cap_bom+1,t.path||(m.bom_code||':'||m.material_code) FROM tree t JOIN public.mfbom_material m ON m.bom_code=t.ma_btp_vt||'-'||t.bom_version WHERE NOT(m.bom_code||':'||m.material_code=ANY(t.path))), data AS (SELECT t.*,b.uom dvt_sp,b.bom_version ver,b.product_quantity sl_sp,(SELECT max(r.material_code) FROM public.mfbom_material_replace r WHERE r.bom_code=t.bom_code AND r.product_code=t.ma_sp_con) material_code_replace,(SELECT max(i.material_code) FROM public.mfbom_material_indirect i WHERE i.bom_code=t.bom_code AND i.product_code=t.ma_sp_con) material_code_phu FROM tree t JOIN public.mfbom b ON b.bom_code=t.bom_code), filtered AS (SELECT d.* FROM data d CROSS JOIN s WHERE (s.ma_sp_me='' OR d.ma_sp_me=ANY(string_to_array(s.ma_sp_me,',')) OR d.ma_sp_con=ANY(string_to_array(s.ma_sp_me,','))) AND (s.ma_sp_con='' OR d.ma_sp_con=ANY(string_to_array(s.ma_sp_con,','))) AND (s.ma_btp_vt='' OR d.ma_btp_vt=ANY(string_to_array(s.ma_btp_vt,','))) AND (s.ma_cong_doan='' OR d.operation_code=ANY(string_to_array(s.ma_cong_doan,',')))), rows AS (SELECT f.ma_sp_me,NULL::text ma_sp_con,NULL::text ma_btp_vt,NULL::integer cap_bom,0 seq,NULL::text dvt_sp,NULL::text ver,NULL::numeric sl_sp,NULL::text uom,NULL::text operation_code,NULL::date valid_from,NULL::date valid_to,NULL::numeric quantity,NULL::numeric sl_sp_material,NULL::numeric sl_gate_runner,NULL::text material_code_replace,NULL::text material_code_phu FROM (SELECT DISTINCT f.ma_sp_me FROM filtered f CROSS JOIN s WHERE s.ma_sp_con='' AND s.ma_btp_vt='' AND s.ma_cong_doan='') f UNION ALL SELECT ma_sp_me,ma_sp_con,ma_btp_vt,cap_bom,1,dvt_sp,ver,sl_sp,uom,operation_code,valid_from,valid_to,quantity,sl_sp_material,sl_gate_runner,material_code_replace,material_code_phu FROM filtered), numbered AS (SELECT row_number() OVER(ORDER BY ma_sp_me,seq,cap_bom NULLS FIRST,ma_btp_vt NULLS FIRST) stt,r.*,count(*) OVER() total FROM rows r) SELECT n.stt,n.ma_sp_me,mother.ten_vt ten_sp_me,mother.model model_sp_me,n.ma_sp_con,child.ten_vt ten_sp_con,n.dvt_sp,n.ver,n.sl_sp,n.ma_btp_vt,material.ten_vt ten_btp_vt,n.uom dvt,n.operation_code ma_cong_doan,material.model model_btp,n.cap_bom,n.valid_from valid_from1,n.valid_to valid_to1,n.quantity sl_dinh_muc,n.sl_sp_material,n.sl_gate_runner,n.material_code_replace,n.material_code_phu,n.total FROM numbered n LEFT JOIN public.dmvt mother ON mother.ma_vt=n.ma_sp_me LEFT JOIN public.dmvt child ON child.ma_vt=n.ma_sp_con LEFT JOIN public.dmvt material ON material.ma_vt=n.ma_btp_vt ORDER BY n.stt LIMIT(SELECT lim FROM p);
